/**
 * Get platforms by educational stream
 */
function getPlatformsByStream(stream) {
  if (!stream || stream === 'all') return PLATFORMS_350;
  return PLATFORMS_350.filter(p => p.stream.toLowerCase() === stream.toLowerCase());
}

/**
 * Search platforms by keyword
 */
function searchPlatforms(keyword) {
  if (!keyword) return PLATFORMS_350;
  const term = keyword.toLowerCase().trim();
  return PLATFORMS_350.filter(p =>
    p.name.toLowerCase().includes(term) ||
    p.category.toLowerCase().includes(term) ||
    p.badge.toLowerCase().includes(term) ||
    p.stream.toLowerCase().includes(term)
  );
}

module.exports = {
  PLATFORMS_350,
  STREAM_CATEGORIES,
  COURSES_CATALOG,
  getPlatformsByStream,
  searchPlatforms,
};

